"""merge_train.py autoqueue|step|record|verify: the merge train. Queued pull requests land in batches, one CI run per
batch.

A pull request joins the queue when the label `queue` is added, by the repository owner or by the review App;
`record` (run on that label event) notes the head commit that was queued, as a comment by the review App. Anyone else
adding the label is refused.

`autoqueue` (run before each scheduled or CI-triggered round) queues, as the review App, every open, ready pull
request from a branch of this repository into main that is not labelled `hold`, once all of these hold on its current
head: the newest ci-ok check run passed; GitHub reports it mergeable (not dirty); the checks "Codacy Static Code
Analysis" and names-issue passed (absent is not ready); no top-level Codex review comment marked P0 or P1 is without
a reply from someone else; and no other open pull request's head commit is among its commits (a stacked pull request
waits until the one below it lands). It also skips a head that already failed alone in a train (train-failed) or was
taken out for changing workflows. Calls: one list of open pull requests, then per candidate, stopping at the first
unmet condition, its check runs, the pull request (mergeable), its review comments, its issue comments, its commits.
The owner keeps control with the label `hold`: it keeps a pull request out of autoqueue, takes it out of the queue,
and closes an open train that holds it (the train is retried without it).

Merging directly stays possible at any time: a queued pull request merged or closed elsewhere just drops out of the
queue; one whose head moved past the recorded commit is taken out with one comment (and autoqueue may queue the new
head once it is ready); an open train whose base main moved, or that holds a pull request that was closed or put on
hold, is closed and retried with its still-queued pull requests on the new main.

`step` (run on a schedule and on train events) does one round:
  1. a train pull request that closed is handled once (label train-done): merged, its pull requests are closed with
     "Landed in #N." (only those whose head is still the batched commit); closed without merging, it is bisected;
  2. while a train is open nothing else happens, except: ci-ok failed on it -> it is closed and bisected; main moved
     under it (it can no longer merge) -> it is closed and the same pull requests are retried;
  3. with no train open, a new one is built from main: the first pending bisect half, or else the queue in label
     order, each head merged with `git merge --no-ff` (conflicts are skipped and stay queued), at most 8; it is pushed
     as train/<n>, opened as "Merge train: #a, #b" with label `train`, and set to auto-merge (squash).
A failed train of several pull requests splits: the first half goes next, the second half waits. A failed train of
one takes that pull request out of the queue (label train-failed). The pending halves live in the train pull
request's body (and its labels), never in files.

`verify` checks a green train: its tree must be exactly
main plus the queued commits named in its body, each queued by the owner or the review App.

Standard library only; GitHub is reached through the `gh` CLI and git through `git`, both via `Runner`, which tests
replace.
"""
import argparse, base64, dataclasses, json, os, re, subprocess, sys

FOOTER = "\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_"
CAP = 8
QUEUE, TRAIN, DONE, FAILED, RETRY, HOLD = "queue", "train", "train-done", "train-failed", "train-retry", "hold"
CODEX_LOGIN = "chatgpt-codex-connector[bot]"
BLOCKING_BADGES = ("P0 Badge", "P1 Badge")
CODACY, NAMES_ISSUE = "Codacy Static Code Analysis", "names-issue"
ACTIONS_LOGIN = "github-actions[bot]"     # the workflow token: pushes and opens trains
STATE_RE = re.compile(r"<!-- merge-train-state (\{.*?\}) -->", re.S)
QUEUED_RE = re.compile(r"<!-- merge-train:queued ([0-9a-f]{40}) -->")
FAILED_RE = re.compile(r"<!-- merge-train:failed ([0-9a-f]{40}) -->")
WORKFLOWS_RE = re.compile(r"<!-- merge-train:workflows ([0-9a-f]{40}) -->")
WORKFLOWS = ".github/workflows/"
BAD = {"failure", "timed_out", "cancelled", "action_required", "startup_failure", "stale"}
# Match pr_issue.py's keywords and exemptions (#123), but only accept ASCII issue numbers:
# int() would otherwise turn Unicode digits into unintended GitHub closing references.
CLOSING = re.compile(r"(?<![\w/#-])(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)[ \t]*:?[ \t]+#([0-9]+)\b", re.IGNORECASE)
EXEMPT_LABEL = "no-issue"
EXEMPT_AUTHORS = {"dependabot[bot]", "chatgpt-codex-connector[bot]"}
DOCS_FILE = re.compile(r"\.md$|^mpvfx-swift/docs/|^(LICENSE|LICENSE-MIT|LICENSE-APACHE|NOTICE)$")
DOCS_MAX_FILES = 3000
BODY_MAX_CHARS = 65536


class Error(Exception):
    pass


@dataclasses.dataclass
class PR:
    number: int
    head_sha: str = ""
    head_ref: str = ""
    same_repo: bool = True
    draft: bool = False
    labels: set = dataclasses.field(default_factory=set)
    state: str = "open"
    merged: bool = False
    author: str = ""
    body: str = ""
    base: str = "main"
    title: str = ""


@dataclasses.dataclass
class Queued:
    number: int
    sha: str
    label_time: str = ""


# ---- planning (pure) -------------------------------------------------------------------------------------------

def order_queue(entries):
    """Queued pull requests in the order their label was added; without a time, by number, after the timed ones."""
    return sorted(entries, key=lambda q: (not q.label_time, q.label_time, q.number))


def parse_state(body):
    m = STATE_RE.search(body or "")
    if not m:
        return None
    try:
        s = json.loads(m.group(1))
        return {"branch": str(s.get("branch", "")), "main": str(s.get("main", "")),
                "prs": [(int(n), str(sha)) for n, sha in s.get("prs", [])],
                "pending": [[int(n) for n in g] for g in s.get("pending", []) if g]}
    except (ValueError, TypeError):
        return None


def halves(numbers):
    k = (len(numbers) + 1) // 2
    return [g for g in (list(numbers[:k]), list(numbers[k:])) if g]


def failed(train):
    return train.state == "closed" and not train.merged and RETRY not in train.labels


def pending_after(train):
    """The bisect groups still to run once `train` (closed) is handled, first group next."""
    st = parse_state(train.body) if train else None
    if not st:
        return []
    nums = [n for n, _ in st["prs"]]
    if train.merged:
        return st["pending"]
    if RETRY in train.labels:
        return [nums] + st["pending"]
    return (halves(nums) if len(nums) > 1 else []) + st["pending"]


def plan_candidate_groups(latest, queue):
    """[(candidates, pending after them)]: each bisect group in turn (only its still-queued members), then the queue.
    The caller builds from the first group that yields a non-empty batch."""
    by_number = {q.number: q for q in queue}
    groups = [[by_number[n] for n in g if n in by_number] for g in pending_after(latest)]
    out = []
    for i, g in enumerate(groups):
        if g:
            out.append((g, [[q.number for q in h] for h in groups[i + 1:] if h]))
    out.append((order_queue(queue), []))
    return out


def build_batch(git, base, candidates, cap=CAP):
    """Merge candidates onto base in order. Returns (batch, skipped) where skipped is [(Queued, reason, in_batch)]
    and reason is "conflict" or "workflows"."""
    git.start(base)
    batch, skipped = [], []
    for q in candidates:
        if len(batch) >= cap:
            break
        if any(f.startswith(WORKFLOWS) for f in git.changed_files(base, q.sha)):
            skipped.append((q, "workflows", []))
        elif git.merge(q.sha, f"Merge #{q.number} ({q.sha[:12]}) into the train"):
            batch.append(q)
        else:
            skipped.append((q, "conflict", [b.number for b in batch]))
    return batch, skipped


def refs(numbers):
    return ", ".join(f"#{n}" for n in numbers)


def train_title(batch):
    return "Merge train: " + refs(q.number for q in batch)


def closing_issues(prs):
    """Issue numbers in carried PR/body order, with each number emitted only once."""
    return list(dict.fromkeys(int(m.group(1)) for pr in prs for m in CLOSING.finditer(pr.body or "")))


def issue_exempt(pr, files):
    return (EXEMPT_LABEL in pr.labels or pr.author in EXEMPT_AUTHORS or
            (0 < len(files) < DOCS_MAX_FILES and all(DOCS_FILE.search(f) for f in files)))


def render_body(branch, main, batch, pending, carried=()):
    state = json.dumps({"branch": branch, "main": main, "prs": [[q.number, q.sha] for q in batch],
                        "pending": pending}, separators=(",", ":"))
    lines = ["Lands these pull requests together after one CI run, as one squash commit.", ""]
    lines += [f"- #{q.number} at `{q.sha}`" for q in batch]
    issues = closing_issues(carried)
    if issues:
        lines += [""] + [f"Closes #{n}" for n in issues]
    lines += ["", f"Built on main at `{main}`."]
    if pending:
        lines += ["", "Waiting for this train (bisecting an earlier failure): " + "; then ".join(refs(g) for g in pending)]
    lines += ["", "If ci-ok passes, this train merges. If it fails, the train is closed "
              "and split in two; a pull request that fails on its own leaves the queue with the label train-failed.",
              "", f"<!-- merge-train-state {state} -->"]
    return "\n".join(lines) + FOOTER


def next_words(pending, queue_left=True):
    if not pending:
        return "Next: the queue continues as usual." if queue_left else "Next: nothing is waiting."
    first, rest = pending[0], pending[1:]
    s = f"Next: {refs(first)} go in the next train"
    if rest:
        s += "; " + "; then ".join(refs(g) for g in rest) + " follow"
    return s + "; the rest of the queue waits until these are done."


# ---- GitHub and git ---------------------------------------------------------------------------------------------

class Runner:
    """Runs a command; returns (returncode, stdout, stderr). Tests pass their own callable instead."""

    def __call__(self, args, env=None, cwd=None):
        full = dict(os.environ, **(env or {}))
        p = subprocess.run(args, env=full, cwd=cwd, capture_output=True, text=True)
        return p.returncode, p.stdout, p.stderr


class GitHub:
    def __init__(self, repo, owner, app_login, push_token="", run=None):
        self.repo, self.owner, self.app_login, self.push_token = repo, owner, app_login, push_token
        self.run = run or Runner()

    def _gh(self, args, env=None, check=True):
        rc, out, err = self.run(["gh"] + args, env=env)
        if rc != 0 and check:
            raise Error(f"gh {' '.join(args[:3])}: {err.strip()[:500]}")
        return rc, out

    def _api(self, path, method="GET", fields=(), jq=None, paginate=False, env=None, check=True):
        args = ["api", "-X", method, path]
        for k, v in fields:
            args += ["-f", f"{k}={v}"]
        if paginate:
            args.append("--paginate")
        if jq:
            args += ["--jq", jq]
        rc, out = self._gh(args, env=env, check=check)
        return rc, out

    def _lines(self, path, jq=".[]"):
        _, out = self._api(path, jq=jq, paginate=True)
        return [json.loads(line) for line in out.splitlines() if line.strip()]

    @staticmethod
    def _pr(d):
        return PR(number=d["number"], head_sha=d["head"]["sha"], head_ref=d["head"]["ref"],
                  same_repo=bool(d["head"].get("repo")) and d["head"]["repo"]["full_name"] == d["base"]["repo"]["full_name"],
                  draft=bool(d.get("draft")), labels={l["name"] for l in d.get("labels", [])}, state=d["state"],
                  merged=bool(d.get("merged_at")), author=d["user"]["login"], body=d.get("body") or "",
                  base=d["base"]["ref"])

    def open_prs(self):
        return [self._pr(d) for d in self._lines(f"repos/{self.repo}/pulls?state=open&per_page=100")]

    def get_pr(self, n):
        _, out = self._api(f"repos/{self.repo}/pulls/{n}")
        return self._pr(json.loads(out))

    def train_prs(self):
        """Train pull requests, newest first (the 30 newest are plenty: one is open at a time)."""
        _, out = self._api(f"repos/{self.repo}/issues?labels={TRAIN}&state=all&sort=created&direction=desc&per_page=30")
        trains = []
        for d in json.loads(out):
            if "pull_request" not in d:
                continue
            if d["state"] == "open":
                trains.append(self.get_pr(d["number"]))
            else:
                trains.append(PR(number=d["number"], labels={l["name"] for l in d.get("labels", [])}, state="closed",
                                 merged=bool(d["pull_request"].get("merged_at")), author=d["user"]["login"],
                                 body=d.get("body") or ""))
        return trains

    def queue_label_event(self, n):
        """(action, time, actor) of the last `queue` label event, or None."""
        last = None
        for e in self._lines(f"repos/{self.repo}/issues/{n}/events?per_page=100"):
            if e.get("event") in ("labeled", "unlabeled") and (e.get("label") or {}).get("name") == QUEUE:
                last = (e["event"], e.get("created_at", ""), (e.get("actor") or {}).get("login", ""))
        return last

    def app_comments(self, n):
        return [c.get("body") or "" for c in self._lines(f"repos/{self.repo}/issues/{n}/comments?per_page=100")
                if (c.get("user") or {}).get("login") == self.app_login]

    def comment(self, n, text):
        self._api(f"repos/{self.repo}/issues/{n}/comments", "POST", [("body", text + FOOTER)])

    def add_labels(self, n, labels):
        self._api(f"repos/{self.repo}/issues/{n}/labels", "POST", [("labels[]", l) for l in labels])

    def remove_label(self, n, label):
        self._api(f"repos/{self.repo}/issues/{n}/labels/{label}", "DELETE", check=False)   # absent is fine

    def set_state(self, n, state):
        self._api(f"repos/{self.repo}/pulls/{n}", "PATCH", [("state", state)])

    def create_pr(self, branch, title, body):
        """Opened with the workflow token when it may (then reopened by the App so CI starts); else with the App token.
        Returns (number, author)."""
        fields = [("title", title), ("head", branch), ("base", "main"), ("body", body)]
        path = f"repos/{self.repo}/pulls"
        if self.push_token:
            rc, out = self._api(path, "POST", fields, jq=".number", env={"GH_TOKEN": self.push_token}, check=False)
            if rc == 0:
                return int(out.strip()), ACTIONS_LOGIN
        _, out = self._api(path, "POST", fields, jq=".number")
        return int(out.strip()), self.app_login

    def enable_auto_merge(self, n, sha):
        rc, _ = self._gh(["pr", "merge", str(n), "-R", self.repo, "--auto", "--squash", "--match-head-commit", sha],
                         check=False)
        return rc == 0

    def all_check_runs(self, sha):
        return self._lines(f"repos/{self.repo}/commits/{sha}/check-runs?per_page=100", ".check_runs[]")

    def check_runs(self, sha):
        return actions_runs(self.all_check_runs(sha))

    def mergeable(self, n):
        """(mergeable, mergeable_state) of a pull request; mergeable is None while GitHub is still computing it."""
        _, out = self._api(f"repos/{self.repo}/pulls/{n}", jq="[.mergeable, .mergeable_state]")
        m, state = json.loads(out)
        return m, state or ""

    def review_comments(self, n):
        return self._lines(f"repos/{self.repo}/pulls/{n}/comments?per_page=100")

    def commit_shas(self, n):
        return {c["sha"] for c in self._lines(f"repos/{self.repo}/pulls/{n}/commits?per_page=100")}

    def run_url(self, sha):
        _, out = self._api(f"repos/{self.repo}/actions/runs?head_sha={sha}&per_page=20",
                           jq='[.workflow_runs[] | select(.name == "mpvfx-ci") | .html_url][0] // ""')
        return out.strip()

    def main_sha(self):
        _, out = self._api(f"repos/{self.repo}/branches/main", jq=".commit.sha")
        return out.strip()


def actions_runs(runs):
    """Check runs made by GitHub Actions (only those count as ci-ok)."""
    return [c for c in runs if (c.get("app") or {}).get("slug") == "github-actions"]


def check_state(runs, name):
    """'success', 'failure', 'pending' or 'absent' for the newest check run called name."""
    named = sorted((c for c in runs if c.get("name") == name), key=lambda c: c.get("id", 0))
    if not named:
        return "absent"
    if named[-1].get("status") != "completed":
        return "pending"
    return "success" if named[-1].get("conclusion") == "success" else "failure"


def open_codex_findings(comments):
    """Ids of top-level Codex review comments marked P0 or P1 that nobody but Codex answered."""
    def login(c):
        return (c.get("user") or {}).get("login", "")
    answered = {c.get("in_reply_to_id") for c in comments if c.get("in_reply_to_id") and login(c) != CODEX_LOGIN}
    return [c["id"] for c in comments
            if login(c) == CODEX_LOGIN and not c.get("in_reply_to_id") and c.get("id") not in answered
            and any(b in (c.get("body") or "") for b in BLOCKING_BADGES)]


def ci_ok(runs):
    """'success', 'failure' or 'pending' for the newest ci-ok check run among runs."""
    oks = sorted((c for c in runs if c.get("name") == "ci-ok"), key=lambda c: c.get("id", 0))
    if not oks or oks[-1].get("status") != "completed":
        return "pending"
    return "success" if oks[-1].get("conclusion") == "success" else "failure"


class Git:
    IDENT = {"GIT_AUTHOR_NAME": "mpvfx merge train", "GIT_COMMITTER_NAME": "mpvfx merge train",
             "GIT_AUTHOR_EMAIL": "41898282+github-actions[bot]@users.noreply.github.com",
             "GIT_COMMITTER_EMAIL": "41898282+github-actions[bot]@users.noreply.github.com"}

    def __init__(self, cwd, push_token="", run=None):
        self.cwd, self.push_token, self.run = cwd, push_token, run or Runner()

    def _git(self, *args, check=True, env=None, strip_output=True):
        # No hooks: nothing from a pull request runs. Merging only reads its trees.
        rc, out, err = self.run(["git", "-c", "core.hooksPath=/dev/null", *args], env=dict(self.IDENT, **(env or {})),
                                cwd=self.cwd)
        if rc != 0 and check:
            raise Error(f"git {args[0]}: {err.strip()[:500]}")
        return rc, out.strip() if strip_output else out

    def fetch_main(self):
        self._git("fetch", "-q", "origin", "+refs/heads/main:refs/remotes/origin/main")
        return self._git("rev-parse", "refs/remotes/origin/main")[1]

    def fetch_prs(self, numbers):
        if numbers:
            self._git("fetch", "-q", "origin", *[f"+refs/pull/{n}/head:refs/merge-train/{n}" for n in numbers])
        return {n: self._git("rev-parse", f"refs/merge-train/{n}")[1] for n in numbers}

    def fetch_shas(self, shas):
        if shas:
            self._git("fetch", "-q", "origin", *shas)

    def start(self, base):
        self._git("checkout", "-q", "--detach", "--force", base)
        self._git("reset", "-q", "--hard", base)

    def merge(self, sha, message):
        rc, _ = self._git("merge", "-q", "--no-ff", "--no-edit", "-m", message, sha, check=False)
        if rc != 0:
            if self._git("merge", "--abort", check=False)[0] != 0:
                self._git("reset", "-q", "--hard", "HEAD")
            return False
        return True

    def changed_files(self, base, sha):
        # Count both sides of renames, so moving code to a docs path is not docs-only.
        # NULs preserve raw filenames, including whitespace and names Git would C-quote.
        return self._git("diff", "--name-only", "--no-renames", "-z", f"{base}...{sha}",
                         strip_output=False)[1].split("\0")[:-1]

    def tree(self, rev):
        return self._git("rev-parse", f"{rev}^{{tree}}")[1]

    def head(self):
        return self._git("rev-parse", "HEAD")[1]

    def is_ancestor(self, a, b):
        return self._git("merge-base", "--is-ancestor", a, b, check=False)[0] == 0

    def remote_trains(self):
        out = self._git("ls-remote", "--heads", "origin", "refs/heads/train/*")[1]
        return [line.split("refs/heads/", 1)[1] for line in out.splitlines() if "refs/heads/" in line]

    def push(self, branch):
        """A new branch only (no force). With the workflow token, so the App is not the last pusher."""
        env = {}
        if self.push_token:
            auth = base64.b64encode(f"x-access-token:{self.push_token}".encode()).decode()
            env = {"GIT_CONFIG_COUNT": "1", "GIT_CONFIG_KEY_0": "http.https://github.com/.extraheader",
                   "GIT_CONFIG_VALUE_0": f"AUTHORIZATION: basic {auth}"}
        self._git("push", "-q", "origin", f"HEAD:refs/heads/{branch}", env=env)


# ---- the round ---------------------------------------------------------------------------------------------------

def queued_prs(gh, prs, log):
    """Open, same-repo, ready PRs labelled queue, each with the commit that was queued. A PR on hold, whose label was
    not added by the owner or the App, that has no recorded commit, or that moved past it leaves the queue with a
    comment."""
    out = []
    for pr in prs:
        if QUEUE not in pr.labels or not pr.same_repo or pr.draft or pr.base != "main" or TRAIN in pr.labels:
            continue
        ev = gh.queue_label_event(pr.number)
        recorded = [m for body in gh.app_comments(pr.number) for m in QUEUED_RE.findall(body)]
        why = None
        if HOLD in pr.labels:
            why = f"it has the label `{HOLD}`"
        elif ev and ev[2] not in (gh.owner, gh.app_login):
            why = "only the repository owner can queue pull requests"
        elif not recorded:
            why = "the merge train has no record of which commit was queued"
        elif recorded[-1] != pr.head_sha:
            why = f"new commits were pushed after it was queued (queued `{recorded[-1][:12]}`, head `{pr.head_sha[:12]}`)"
        if why:
            gh.remove_label(pr.number, QUEUE)
            again = (f"Remove `{HOLD}` when it may be queued again." if HOLD in pr.labels else
                     "Add the label `queue` again when it is ready (or let it be queued automatically).")
            gh.comment(pr.number, f"Taken out of the queue: {why}. {again}")
            log.append(f"#{pr.number}: out of the queue ({why})")
            continue
        out.append(Queued(pr.number, pr.head_sha, ev[1] if ev else ""))
    return out


def land(gh, train, log):
    st = parse_state(train.body) or {"prs": []}
    for n, sha in st["prs"]:
        pr = gh.get_pr(n)
        if pr.state == "open" and pr.head_sha == sha:
            gh.comment(n, f"Landed in #{train.number}.")
            gh.remove_label(n, QUEUE)
            gh.set_state(n, "closed")
            log.append(f"#{n}: landed in #{train.number}, closed")
        else:
            log.append(f"#{n}: in #{train.number} at {sha[:12]} but now {pr.state} at {pr.head_sha[:12]}: left as is")


def fail(gh, train, reason, log):
    """Train closed without merging (or about to be): bisect, or take a lone PR out of the queue."""
    st = parse_state(train.body) or {"prs": [], "pending": []}
    nums = [n for n, _ in st["prs"]]
    if not train.head_sha:
        train.head_sha = gh.get_pr(train.number).head_sha
    runs = gh.check_runs(train.head_sha) if train.head_sha else []
    jobs = sorted({c["name"] for c in runs if c.get("conclusion") in BAD and c.get("name") != "ci-ok"})
    link = (gh.run_url(train.head_sha) if train.head_sha else "") or next(
        (c.get("html_url", "") for c in runs if c.get("name") == "ci-ok"), "")
    if len(nums) == 1:
        n, failed_sha = st["prs"][0]
        detail = (f"Failing jobs: {', '.join(jobs)}." if jobs else "No failing job was reported.")
        if link:
            detail += f"\nRun: {link}"
        gh.comment(n, f"<!-- merge-train:failed {failed_sha} -->\n"
                      f"Taken out of the queue: on its own in train #{train.number}, {reason}.\n\n{detail}\n\n"
                      "Fix it, then add the label `queue` again (or push the fix and let it be queued automatically).")
        gh.remove_label(n, QUEUE)
        gh.add_labels(n, [FAILED])
        log.append(f"#{n}: failed alone in #{train.number}: label {FAILED}")
        head = f"{reason.capitalize()}; #{n} was alone in it, so it leaves the queue (label {FAILED}). "
    else:
        head = f"{reason.capitalize()}, so this train is closed without merging and split in two. "
    train.state = "closed"
    gh.comment(train.number, head + next_words(pending_after(train)))
    log.append(f"#{train.number}: {reason}; next groups {pending_after(train)}")


def finish(gh, train, log):
    """Handle a closed train once."""
    if train.merged:
        land(gh, train, log)
    elif RETRY not in train.labels:
        fail(gh, train, "it was closed without merging", log)
    gh.add_labels(train.number, [DONE])


def left_train(gh, st):
    """Members of an open train that are no longer open, or are on hold."""
    if not st.get("prs"):
        return []
    open_ = {p.number: p for p in gh.open_prs()}
    return [n for n, _ in st["prs"] if n not in open_ or HOLD in open_[n].labels]


def next_number(trains, remote):
    used = [0]
    for name in [(parse_state(t.body) or {}).get("branch", "") for t in trains] + [t.head_ref for t in trains] + remote:
        m = re.fullmatch(r"train/(\d+)", name or "")
        if m:
            used.append(int(m.group(1)))
    return max(used) + 1


def step(gh, git, log=None):
    log = [] if log is None else log
    trains = gh.train_prs()
    for t in reversed(trains):
        if t.state == "closed" and DONE not in t.labels:
            finish(gh, t, log)
            t.labels.add(DONE)
    active = [t for t in trains if t.state == "open"]
    main = git.fetch_main()
    if len(active) > 1:
        log.append("more than one train is open (" + refs(t.number for t in active) + "): close all but one")
        return log
    if active:
        t = active[0]
        st = parse_state(t.body) or {}
        ci = ci_ok(gh.check_runs(t.head_sha))
        if ci == "failure":
            fail(gh, t, "ci-ok failed on this train", log)
            gh.add_labels(t.number, [DONE])
            gh.set_state(t.number, "closed")
        elif st.get("main") and st["main"] != main:
            gh.add_labels(t.number, [RETRY, DONE])
            gh.comment(t.number, f"main moved since this train was built (`{st['main'][:12]}` -> `{main[:12]}`), so it "
                                 "can no longer merge. Closed; the next train retries the same pull requests on the "
                                 "new main.")
            gh.set_state(t.number, "closed")
            t.labels |= {RETRY, DONE}
            t.state = "closed"
            log.append(f"#{t.number}: main moved; retrying")
        elif left_train(gh, st):
            gone = left_train(gh, st)
            gh.add_labels(t.number, [RETRY, DONE])
            gh.comment(t.number, f"{refs(gone)} was closed or put on hold after this train was built. Closed; the "
                                 "next train retries the pull requests that are still queued.")
            gh.set_state(t.number, "closed")
            t.labels |= {RETRY, DONE}
            t.state = "closed"
            log.append(f"#{t.number}: {refs(gone)} left; retrying")
        else:
            log.append(f"train #{t.number} is open (ci-ok {ci}); waiting")
            return log
        trains = [t] + [x for x in trains if x is not t]
    latest = next((t for t in trains if t.state == "closed"), None)
    prs = gh.open_prs()
    queue = queued_prs(gh, prs, log)
    if not queue:
        log.append("queue is empty")
        return log
    shas = git.fetch_prs([q.number for q in queue])
    queue = [q for q in queue if shas.get(q.number) == q.sha]
    for candidates, pending in plan_candidate_groups(latest, queue):
        batch, skipped = build_batch(git, main, candidates)
        for q, reason, inb in skipped:
            note_skip(gh, q, reason, inb, main, log)
        if batch:
            break
    else:
        log.append("nothing in the queue merges cleanly on main")
        return log
    n = next_number(trains, git.remote_trains())
    branch = f"train/{n}"
    by_number = {p.number: p for p in prs}
    carried = [by_number[q.number] for q in batch]
    body = render_body(branch, main, batch, pending, carried)
    if len(body) > BODY_MAX_CHARS:
        log.append(f"not opening {branch}: body has {len(body)} characters (limit {BODY_MAX_CHARS}); "
                   f"shorten the closing references in {refs(p.number for p in carried)} before retrying")
        return log
    labels = [TRAIN]
    if not closing_issues(carried) and all(issue_exempt(p, git.changed_files(main, p.head_sha)) for p in carried):
        labels.append(EXEMPT_LABEL)
    git.push(branch)
    head = git.head()
    number, author = gh.create_pr(branch, train_title(batch), body)
    gh.add_labels(number, labels)
    if author == ACTIONS_LOGIN:
        # A pull request opened with the workflow token starts no workflow; reopening it with the App token starts CI.
        gh.set_state(number, "closed")
        gh.set_state(number, "open")
    if not gh.enable_auto_merge(number, head):
        log.append(f"#{number}: auto-merge could not be turned on (Settings > General > Allow auto-merge)")
    log.append(f"opened train #{number} ({branch}): {refs(q.number for q in batch)}; waiting: {pending}")
    return log


def note_skip(gh, q, reason, in_batch, main, log):
    if reason == "workflows":
        gh.remove_label(q.number, QUEUE)
        gh.comment(q.number, f"<!-- merge-train:workflows {q.sha} -->\n"
                             f"Not in this batch: it changes files under `{WORKFLOWS}`, which the merge train's token "
                             "may not push. Land it on its own (merge it once ci-ok passes).")
        log.append(f"#{q.number}: changes workflows; out of the queue")
        return
    marker = f"<!-- merge-train:skipped {q.sha} {main} {','.join(map(str, in_batch))} -->"
    if any(marker in body for body in gh.app_comments(q.number)):
        return
    with_ = f"main or with {refs(in_batch)}" if in_batch else "main"
    gh.comment(q.number, f"{marker}\nNot in this batch: conflicts with {with_}; update it from main. "
                         "It stays queued.")
    log.append(f"#{q.number}: conflicts ({with_}); stays queued")


def record(gh, n, sha, sender, log=None):
    """On a `queue` label event: note the head the owner or the App queued, or undo the label."""
    log = [] if log is None else log
    pr = gh.get_pr(n)
    why = None
    if sender not in (gh.owner, gh.app_login):
        why = "only the repository owner can queue pull requests"
    elif not pr.same_repo or pr.base != "main" or TRAIN in pr.labels:
        why = "only a pull request from a branch of this repository into main can be queued"
    elif HOLD in pr.labels:
        why = f"it has the label `{HOLD}`; remove it first"
    if why:
        gh.remove_label(n, QUEUE)
        gh.comment(n, f"Not queued: {why}.")
        log.append(f"#{n}: not queued ({why})")
        return log
    recorded = [m for body in gh.app_comments(n) for m in QUEUED_RE.findall(body)]
    if recorded and recorded[-1] == sha:
        log.append(f"#{n}: already recorded at {sha}")     # autoqueue's own label: it wrote the record first
        return log
    gh.comment(n, queued_note(sha))
    if FAILED in pr.labels:
        gh.remove_label(n, FAILED)
    log.append(f"#{n}: queued at {sha}")
    return log


def queued_note(sha, auto=False):
    how = (f"Queued automatically at `{sha}`: ci-ok, {CODACY} and {NAMES_ISSUE} passed, it merges cleanly and no "
           f"Codex P0 or P1 finding is unanswered. Add the label `{HOLD}` to keep it out of the queue."
           if auto else f"Queued at `{sha}`.")
    return (f"<!-- merge-train:queued {sha} -->\n{how} The merge train tests it together with other queued pull "
            "requests and lands it; pushing new commits takes it out of the queue.")


def autoqueue_candidate(pr):
    return (pr.state == "open" and pr.same_repo and not pr.draft and pr.base == "main"
            and not pr.labels & {HOLD, QUEUE, TRAIN} and not pr.head_ref.startswith("train/"))


def not_ready(gh, pr, open_prs):
    """Why pr may not be queued at its head yet, or None. Stops at the first unmet condition (fewest calls)."""
    runs = gh.all_check_runs(pr.head_sha)
    ci = ci_ok(actions_runs(runs))
    if ci != "success":
        return f"ci-ok {ci}"
    for name, mine in ((CODACY, runs), (NAMES_ISSUE, actions_runs(runs))):
        state = check_state(mine, name)
        if state != "success":
            return f"{name} {state}"
    mergeable, state = gh.mergeable(pr.number)
    if mergeable is not True or state == "dirty":
        return f"not mergeable ({state or 'unknown'})"
    findings = open_codex_findings(gh.review_comments(pr.number))
    if findings:
        return f"{len(findings)} unanswered Codex P0/P1 finding(s)"
    notes = gh.app_comments(pr.number)
    if FAILED in pr.labels:
        failed_at = [m for b in notes for m in FAILED_RE.findall(b)]
        if not failed_at or failed_at[-1] == pr.head_sha:
            return f"{FAILED} at this head"
    if any(pr.head_sha in WORKFLOWS_RE.findall(b) for b in notes):
        return "changes workflows (lands on its own)"
    others = {p.head_sha: p.number for p in open_prs if p.number != pr.number}
    below = sorted(others[s] for s in gh.commit_shas(pr.number) if s in others)
    if below:
        return f"stacked on {refs(below)}"
    return None


def autoqueue(gh, log=None):
    """Queue, as the App, every ready pull request (see the module docstring). Never comments on one not ready."""
    log = [] if log is None else log
    prs = gh.open_prs()
    for pr in prs:
        if not autoqueue_candidate(pr):
            continue
        try:
            why = not_ready(gh, pr, prs)
            if why:
                log.append(f"#{pr.number}: not ready ({why})")
                continue
            gh.comment(pr.number, queued_note(pr.head_sha, auto=True))    # the record first, then the label
            gh.add_labels(pr.number, [QUEUE])
            if FAILED in pr.labels:
                gh.remove_label(pr.number, FAILED)
            log.append(f"#{pr.number}: queued at {pr.head_sha}")
        except Error as e:      # one pull request's API error does not stop the others or the round
            log.append(f"#{pr.number}: skipped ({e})")
    return log


def verify(gh, git, branch, sha):
    """Problems with green train `branch` at `sha` (empty: none). Returns (pr number, problems)."""
    problems = []
    prs = [p for p in gh.open_prs() if p.head_ref == branch and p.same_repo]
    if len(prs) != 1:
        return None, [f"no single open pull request from {branch}"]
    pr = prs[0]
    if pr.head_sha != sha:
        problems.append(f"head is {pr.head_sha}, not {sha}")
    if TRAIN not in pr.labels or not re.fullmatch(r"train/\d+", pr.head_ref):
        problems.append("not a train (label train, branch train/<n>)")
    if pr.author != ACTIONS_LOGIN:
        problems.append(f"opened by {pr.author}, not by the merge train workflow ({ACTIONS_LOGIN})")
    if pr.base != "main" or pr.draft:
        problems.append("not a ready pull request into main")
    if ci_ok(gh.check_runs(sha)) != "success":
        problems.append(f"ci-ok has not passed on {sha}")
    st = parse_state(pr.body)
    if not st or not st["prs"] or st["branch"] != branch:
        return pr.number, problems + ["no train state in the body"]
    for n, s in st["prs"]:
        ev = gh.queue_label_event(n)
        if not ev or ev[0] != "labeled" or ev[2] not in (gh.owner, gh.app_login):
            problems.append(f"#{n}: its label queue was not added (last) by {gh.owner} or {gh.app_login}")
        if f"<!-- merge-train:queued {s} -->" not in "\n".join(gh.app_comments(n)):
            problems.append(f"#{n}: {s} is not the commit that was queued")
    if problems:
        return pr.number, problems
    # The train's content must be exactly main plus those commits: rebuild it and compare trees.
    main = git.fetch_main()
    git.fetch_shas([sha, st["main"]] + [s for _, s in st["prs"]])
    if not git.is_ancestor(st["main"], main):
        problems.append(f"built on {st['main']}, which is not on main")
    git.start(st["main"])
    for n, s in st["prs"]:
        if not git.merge(s, f"Merge #{n}"):
            problems.append(f"#{n} does not merge cleanly when rebuilding")
    if not problems and git.tree("HEAD") != git.tree(sha):
        problems.append("the train's files differ from main plus the queued commits")
    return pr.number, problems


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("step")
    sub.add_parser("autoqueue")
    r = sub.add_parser("record")
    r.add_argument("--pr", type=int, required=True)
    r.add_argument("--sha", required=True)
    r.add_argument("--sender", required=True)
    v = sub.add_parser("verify")
    v.add_argument("--branch", required=True)
    v.add_argument("--sha", required=True)
    a = ap.parse_args(argv)
    env = os.environ
    gh = GitHub(env["GITHUB_REPOSITORY"], env["OWNER"], env["APP_LOGIN"], env.get("PUSH_TOKEN", ""))
    git = Git(os.getcwd(), env.get("PUSH_TOKEN", ""))
    if a.cmd == "record":
        if not re.fullmatch(r"[0-9a-f]{40}", a.sha):
            raise SystemExit("--sha must be a full commit sha")
        print("\n".join(record(gh, a.pr, a.sha, a.sender)))
    elif a.cmd == "step":
        print("\n".join(step(gh, git)))
    elif a.cmd == "autoqueue":
        print("\n".join(autoqueue(gh)))
    else:
        n, problems = verify(gh, git, a.branch, a.sha)
        for p in problems:
            print(f"::error::{p}")
        if problems:
            return 1
        print(f"train #{n} at {a.sha}: every check passed")
        if env.get("GITHUB_OUTPUT"):
            with open(env["GITHUB_OUTPUT"], "a") as f:
                f.write(f"pr={n}\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
